    "keySignature": "Bb Major",
    "scriptureAnchor": {
      "reference": "Galatians 2:20",
      "text": "I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me.",
      "book": "Galatians",
      "chapter": 2,
      "verse": 20
    },
    "stanzas": [
      {
        "number": 1,
        "text": "A mind at perfect peace with God,\nOh! what a word is this!\nA sinner reconciled through blood;\nThis! this indeed is peace."
      },
      {
        "number": 2,
        "text": "By nature and by practice far,\nHow very far from God!\nYet now by grace brought nigh to Him.\nThrough faith in Jesus' blood."
      },
      {
        "number": 3,
        "text": "So near, so very near to God,\nI cannot nearer be;\nFor in the person of His Son\nI am as near as He."
      },
      {
        "number": 4,
        "text": "So dear, so very dear to God,\nMore dear I cannot be;\nThe love wherewith He loves the Son.\nSuch is His love to me."
      },
      {
        "number": 5,
        "text": "Why should I ever careful be\nSince such a God is mine?\nHe watches o'er me night and day,\nAnd tells me \"Mine is thine.\""
      }
    ],
    "historicalStory": "Written in 1855 by English evangelist Catesby Paget during the mid-19th century British revival awakenings. Drawing on Romans 5:1 and Colossians 1:20, Paget penned these stanzas to testify to the profound interior tranquility granted when a believer understands that Christ's finished work on the Cross has satisfied divine justice forever.",
