    "hymnNumber": 68,
    "title": "Done is the work that saves",
    "category": "Cross & Resurrection",
    "author": "Horatius Bonar",
    "composer": "Traditional (St.)",
    "tuneName": "St.",
    "year": "Historic Hymnal",
    "meter": "6.6.6.6.8.8.",
    "keySignature": "C Major",
    "scriptureAnchor": {
      "reference": "Galatians 2:20",
      "text": "I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me.",
      "book": "Galatians",
      "chapter": 2,
      "verse": 20
    },
    "stanzas": [
      {
        "number": 1,
        "text": "Done is the work that saves,\nOnce and for ever done;\nFinished the righteousness\nThat clothes the unrighteous one.\nThe love that blesses us below\nIs flowing freely to us now."
      },
      {
        "number": 2,
        "text": "The sacrifice is o'er,\nThe veil is rent in twain,\nThe mercy-seat is red\nWith blood of Victim slain.\nWhy stand we then without, in fear?\nThe blood of Christ invites us near."
      },
      {
        "number": 3,
        "text": "The gate is open wide;\nThe new and living way\nIs clear, and free, and bright\nWith love, and peace, and day.\nInto the holiest now we come,\nOur present and our endless home."
      },
      {
        "number": 4,
        "text": "Enthroned in majesty\nThe High Priest sits within;\nHis precious blood, once shed,\nHas made and keeps us clean;\nWith boldness let us now draw near;\nThat blood has banished every fear."
      },
      {
        "number": 5,
        "text": "Then to the Lamb once slain\nBe glory, praise, and power,\nWho died, and lives again,\nWho liveth evermore;\nWho loved us, cleansed us by His blood,\nAnd made us kings and priests to God."
      }
    ],
